import { NextResponse } from "next/server";

export function proxy(request: NextRequest) {
  const { method, nextUrl } = request;
  console.log(`[request] ${method} ${nextUrl.pathname}${nextUrl.search}`);

  return NextResponse.next();
}

export const config = {
  matcher: "/:path*",
};

